/**
 ******************************************************************************
 * @file    live_chain_oracle.h
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant.
 * @brief   Test oracle: copies of TomTask's OLD live effect chain (its
 *          upsampler and effect loop), kept for the tests.
 *
 * Until 29 Oct 2026 TomTask applied the selected effect live, inside every
 * 4 ms DMA half (Core/Src/tom_dac_output.c as of 29 Oct 2026, lines
 * 318-369): each 64-sample 32 kHz block went through upsample_block() (2:3,
 * 96 samples at 48 kHz) and then apply_effects() (AudioEffects_ProcessBlock
 * on 64, then on 32 samples). The new code that replaces it (the
 * RateAdapter2to3 and FxRender modules) must produce exactly the same
 * samples, so the tests compare it with these copies ("the oracle": the
 * known-good answer). The copies call today's AudioEffects module, so they
 * pin down the chain around the effects, not the effects' own sound (Echo
 * is now 240 ms instead of 120 ms).
 *
 * Test helper only: not part of the firmware.
 ******************************************************************************
 */
#ifndef LIVE_CHAIN_ORACLE_H
#define LIVE_CHAIN_ORACLE_H

#include <stdint.h>

#include "audio_effects.h"

/** The old upsampler alone: its memory (s_last_in) back to 0. */
void Oracle_UpsamplerReset(void);

/** The old upsample_block(): n (1..64) samples at 32 kHz -> (3 n) / 2 at 48 kHz. */
uint32_t Oracle_UpsampleBlock(const int16_t *in_32k, uint32_t n, int16_t *out_48k);

/**
 * The live chain's set-up for a playback with effect mode, in TomTask's own
 * order: AudioEffects_Init (Tom_Init), SetMode + Reset (TOM_CMD_SET_EFFECT),
 * then the upsampler and Reset again (TOM_CMD_SOURCE_PLAYBACK).
 */
void Oracle_LiveChainBegin(AudioEffectMode mode);

/** One 32 kHz block (1..64 samples) through the old chain; returns the 48 kHz samples written. */
uint32_t Oracle_LiveChainBlock(const int16_t *in_32k, uint32_t n, int16_t *out_48k);

#endif
